//! Dynamic-library FFI for MatCraft's `loadlibrary`/`calllib`.
//!
//! This crate is the project's single unsafe boundary (`forbid(unsafe_code)`
//! is relaxed here and here only). `libloading` resolves symbols; calls go
//! through exact-signature function-pointer dispatch generated by a macro —
//! each leaf transmutes the raw address to the concrete
//! `extern "C" fn(…) -> R` type that matches the argument values actually
//! passed, so doubles land in XMM registers and integers/pointers in GPRs
//! on both x86_64 ABIs. No libffi C dependency.
//!
//! Caveats that come with raw FFI (documented in `docs/language.md`):
//! - A buggy callee can corrupt or crash the host process; signatures are
//!   trusted as declared.
//! - Integer/pointer arguments pass in one 64-bit GPR slot, so callee-side
//!   narrower C types (`int`, `short`, `char`, `_Bool`) see the low bits —
//!   the same convention libffi applies for C decl calls.
//! - `single`/`float` arguments are exact (`f32` leaf); `long double`,
//!   structs-by-value and SIMD types are not supported.

use object::Object as _;
use std::collections::BTreeSet;
use std::fmt;
use std::path::{Path, PathBuf};

/// Errors are plain strings so `matlang` can wrap them as `LangError`.
#[derive(Debug, Clone)]
pub struct FfiError(pub String);

impl fmt::Display for FfiError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for FfiError {}

fn err(msg: impl Into<String>) -> FfiError {
    FfiError(msg.into())
}

/// A loaded shared library (`loadlibrary` handle).
pub struct Lib {
    path: PathBuf,
    lib: libloading::Library,
}

impl fmt::Debug for Lib {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Lib").field("path", &self.path).finish()
    }
}

/// One marshalled call argument — the register class of the Rust value
/// decides which register the callee reads it from.
#[derive(Debug, Clone, Copy)]
pub enum Scalar {
    /// Integer, `bool` or any pointer (buffer address, raw address).
    I(u64),
    /// `float` (32-bit) — exact, no double promotion.
    S(f32),
    /// `double` (64-bit).
    F(f64),
}

/// Which register/semantics to read back after the call.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RetKind {
    Void,
    F32,
    F64,
    /// All integer, bool and pointer returns read through a 64-bit GPR.
    U64,
}

/// The call's raw result, before C-type interpretation.
#[derive(Debug, Clone, Copy)]
pub enum RetVal {
    Void,
    F32(f32),
    F64(f64),
    U64(u64),
}

/// Maximum positional arguments accepted by `invoke`.
pub const MAX_ARGS: usize = 6;

impl Lib {
    /// `dlopen`/`LoadLibrary` — resolves the path, loads the library.
    pub fn load(path: &Path) -> Result<Self, FfiError> {
        // SAFETY: loading a shared object runs its constructors; this is
        // the documented contract of `loadlibrary` and cannot be made
        // safer — the path comes from the user's own script.
        let lib = unsafe { libloading::Library::new(path) }.map_err(|e| err(format!("cannot load '{}': {e}", path.display())))?;
        Ok(Lib { path: path.to_path_buf(), lib })
    }

    /// The alias MatCraft uses for this library: the file stem.
    pub fn alias(&self) -> String {
        self.path.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_else(|| self.path.display().to_string())
    }

    /// Raw symbol address for `name` — stays valid while `self` is alive.
    pub fn sym_addr(&self, name: &str) -> Result<usize, FfiError> {
        let mut n = String::with_capacity(name.len() + 1);
        n.push_str(name);
        n.push('\0');
        // SAFETY: `n` is NUL-terminated by construction; the returned
        // pointer is only converted to an address, never dereferenced
        // past the `Symbol` lifetime guard (we discard the wrapper and
        // keep the library alive in the map that owns `self`).
        let sym: libloading::Symbol<'_, *mut core::ffi::c_void> =
            unsafe { self.lib.get(n.as_bytes()) }.map_err(|e| err(format!("symbol '{name}' not found in '{}': {e}", self.path.display())))?;
        Ok(*sym as usize)
    }

    /// Exported symbol names — backs `libfunctions`/`libfunctionsview`.
    /// Reads the file's own export table via `object` (PE/ELF/Mach-O).
    pub fn exports(&self) -> Result<Vec<String>, FfiError> {
        let bytes = std::fs::read(&self.path).map_err(|e| err(format!("cannot read '{}': {e}", self.path.display())))?;
        let file = object::File::parse(&*bytes).map_err(|e| err(format!("cannot parse '{}': {e}", self.path.display())))?;
        let mut names = BTreeSet::new();
        for ex in file.exports().map_err(|e| err(format!("cannot list exports of '{}': {e}", self.path.display())))? {
            if let Ok(s) = std::str::from_utf8(ex.name()) {
                names.insert(s.to_string());
            }
        }
        Ok(names.into_iter().collect())
    }
}

// Combinatorial exact-signature dispatch. Each `match` leaf transmutes
// the target address to the `extern "C" fn(T0,…,Tn) -> R` type whose
// parameter types equal the Rust types of the bound variables — so the
// call-site ABI places every argument exactly where a C-decl callee
// expects it. `$ty` accumulates the leaf's parameter type list.
macro_rules! ffi_combo {
    ($addr:expr, $ret:ty; []; [$($ty:ty),*]; [$($b:expr),*]) => {{
        let f: unsafe extern "C" fn($($ty),*) -> $ret = ::std::mem::transmute($addr);
        unsafe { f($($b),*) }
    }};
    ($addr:expr, $ret:ty; [$a:ident $(, $rest:ident)*]; [$($ty:ty),*]; [$($b:expr),*]) => {
        match *$a {
            Scalar::I(v) => ffi_combo!($addr, $ret; [$($rest),*]; [$($ty,)* u64]; [$($b,)* v]),
            Scalar::S(v) => ffi_combo!($addr, $ret; [$($rest),*]; [$($ty,)* f32]; [$($b,)* v]),
            Scalar::F(v) => ffi_combo!($addr, $ret; [$($rest),*]; [$($ty,)* f64]; [$($b,)* v]),
        }
    };
}

/// Calls `addr` with `args` and reads the result per `ret`.
///
/// # Safety contract (enforced by construction, documented for callers)
/// The caller must guarantee `addr` points to a function whose true C
/// signature is compatible with `args`/`ret`. There is no runtime check —
/// a wrong declaration is undefined behaviour at the ABI level, exactly
/// like a mistyped `calllib` signature.
pub fn invoke(addr: usize, ret: RetKind, args: &[Scalar]) -> Result<RetVal, FfiError> {
    if args.len() > MAX_ARGS {
        return Err(err(format!("calllib supports at most {MAX_ARGS} arguments")));
    }
    // SAFETY: each macro leaf performs one transmute to the signature the
    // leaf itself passes — argument register classes are therefore always
    // consistent between the call site and the declared fn type. Returns
    // `None` only for arities outside the handled range (kept defensive:
    // `invoke` rejects them first, but nothing here may panic).
    unsafe fn call<R>(addr: usize, args: &[Scalar]) -> Option<R> {
        Some(match args {
            [] => ffi_combo!(addr, R; []; []; []),
            [a0] => ffi_combo!(addr, R; [a0]; []; []),
            [a0, a1] => ffi_combo!(addr, R; [a0, a1]; []; []),
            [a0, a1, a2] => ffi_combo!(addr, R; [a0, a1, a2]; []; []),
            [a0, a1, a2, a3] => ffi_combo!(addr, R; [a0, a1, a2, a3]; []; []),
            [a0, a1, a2, a3, a4] => ffi_combo!(addr, R; [a0, a1, a2, a3, a4]; []; []),
            [a0, a1, a2, a3, a4, a5] => ffi_combo!(addr, R; [a0, a1, a2, a3, a4, a5]; []; []),
            _ => return None,
        })
    }
    let out = match ret {
        RetKind::Void => unsafe { call::<()>(addr, args) }.map(|()| RetVal::Void),
        RetKind::F32 => unsafe { call::<f32>(addr, args) }.map(RetVal::F32),
        RetKind::F64 => unsafe { call::<f64>(addr, args) }.map(RetVal::F64),
        RetKind::U64 => unsafe { call::<u64>(addr, args) }.map(RetVal::U64),
    };
    out.ok_or_else(|| err(format!("calllib supports at most {MAX_ARGS} arguments")))
}

/// Reads a NUL-terminated C string at `addr` (for `cstring` returns).
/// Returns `None` for a NULL pointer.
pub fn read_cstring(addr: usize) -> Option<String> {
    if addr == 0 {
        return None;
    }
    // SAFETY: `addr` is trusted as a valid `char*` per the declared
    // signature — the documented contract of a `cstring` return. The
    // read is bounded to 1 MiB so a non-terminated pointer reports a
    // bounded region instead of scanning forever.
    unsafe {
        let mut len = 0usize;
        let p = addr as *const u8;
        const CAP: usize = 1 << 20;
        while len < CAP && *p.add(len) != 0 {
            len += 1;
        }
        if len == CAP {
            return Some(String::from("[unterminated cstring]"));
        }
        let bytes = std::slice::from_raw_parts(p, len);
        Some(String::from_utf8_lossy(bytes).into_owned())
    }
}
